            description,
            structural.map(|s| s.tags.clone()).unwrap_or_default(),
            structural.and_then(|s| s.parent.clone()),
            structural.map(|s| s.declarations.clone()).unwrap_or_default(),
        )
        .degraded_also_by(&unread_kinds);
