        let mut hasher = FxHasher::default();
        self.name.hash(&mut hasher);
        self.required.hash(&mut hasher);
        self.react_declared.hash(&mut hasher);
        self.description.hash(&mut hasher);
        self.prop_type.structural_hash(&mut hasher);
        hasher.finish()
