"""Compare caliper's structural and checker outputs over gate-large, per component and prop."""
import json
import sys
from collections import Counter

DIR = "/tmp/claude-501/s7/"


def load(name):
    d = json.load(open(DIR + name + ".json"))
    out = {}
    for key, c in d["components"].items():
        props = {}
        for set_id in c["props"]:
            for pname, pid in d["propSets"][set_id].items():
                props[pname] = d["props"][pid]
        out[key] = props
    return out


def kinds(t, acc):
    if isinstance(t, dict):
        k = t.get("kind")
        if k:
            acc[k] += 1
        for v in t.values():
            kinds(v, acc)
    elif isinstance(t, list):
        for v in t:
            kinds(v, acc)


def top(t):
    return t.get("kind") if isinstance(t, dict) else str(t)


runs = {n: load(n) for n in sys.argv[1:]}
for n, comps in runs.items():
    with_props = sum(1 for p in comps.values() if p)
    total = sum(len(p) for p in comps.values())
    lib = Counter()
    for k, p in comps.items():
        lib[k[:4]] += len(p)
    print(f"{n}: components {len(comps)}, with props {with_props}, props {total}, by prefix {dict(lib)}")

if "gl-full" in runs and "gl-checker" in runs:
    s, c = runs["gl-full"], runs["gl-checker"]
    verdict = Counter()
    top_kinds = Counter()
    for key, cprops in c.items():
        sprops = s.get(key, {})
        for name, cp in cprops.items():
            sp = sprops.get(name)
            if sp is None:
                verdict["checker only"] += 1
            elif sp["type"] == cp["type"]:
                verdict["same type json"] += 1
                top_kinds[top(sp["type"])] += 1
            else:
                verdict["different type json"] += 1
        for name in sprops:
            if name not in cprops:
                verdict["structural only"] += 1
    print("structural vs checker per prop:", dict(verdict))
    print("top kinds of same-type props:", top_kinds.most_common(12))
    # Degraded markers in the checker answer
    deg = Counter()
    for cprops in c.values():
        for cp in cprops.values():
            for r in cp.get("degradedBy") or []:
                deg[r] += 1
    print("checker degradedBy:", deg.most_common(10))

